import json, hashlib, subprocess
from pathlib import Path

repo=Path("/Users/steventran/do-again")
key=hashlib.sha256(str(repo.resolve()).encode()).hexdigest()[:12]
root=Path.home()/".do_again/projects"/key
state=root/"state"
control=root/"control"

def read_json(p):
    try:
        v=json.loads(p.read_text())
        return v if isinstance(v,dict) else {}
    except Exception:
        return {}

def names(d):
    return sorted(p.stem for p in d.glob("*.json")) if d.is_dir() else []

liveness=read_json(state/"liveness.json")
browser=read_json(state/"browser_status.json")
outbox=names(state/"browser_outbox")
requests=names(control/"automation/do_again/requests")
receipts=set(names(control/"automation/do_again/receipts"))
pending=[r for r in requests if r not in receipts]

print(json.dumps({
  "repo":str(repo),
  "liveness":liveness,
  "browser_status":browser,
  "outbox_ids":outbox,
  "pending_requests":pending,
  "ci_proof_request_present":"selfdev-live-ci-handoff-proof-20261007-101" in requests,
  "ci_proof_receipt_present":"selfdev-live-ci-handoff-proof-20261007-101" in receipts,
},indent=2,sort_keys=True))

# Acceptance assertions: terminal CI event persisted, no duplicate pending work/outbox for proof request.
if liveness.get("goal_state")!="waiting_for_ci":
    raise SystemExit("expected durable waiting_for_ci goal state")
if not liveness.get("ci_terminal_fingerprint"):
    raise SystemExit("missing terminal CI fingerprint")
if liveness.get("ci",{}).get("run_id") != 37723478310:
    raise SystemExit("unexpected CI run id")
if "selfdev-live-ci-handoff-proof-20261007-101" in pending:
    raise SystemExit("proof request still pending")
if any("selfdev-live-ci-handoff-proof-20261007-101" in x for x in outbox):
    raise SystemExit("proof request unexpectedly queued in browser outbox")
print("LIVE_CI_HANDOFF_STATE_PROOF_OK")
